create table xxventuri.xxeba_order_products (
    order_products_id number,
    order_id          number,
    product_name      varchar2(255 byte),
    product_price     number,
    currency_type     varchar2(50 byte),
    brand_id          number,
    created           timestamp(6) with local time zone,
    created_by        varchar2(50 byte),
    updated           timestamp(6) with local time zone,
    updated_by        varchar2(50 byte),
    status            varchar2(1 byte),
    quantity          number,
    delivery_date     date,
    product_id        number,
    created_temp      varchar2(100 byte),
    updated_temp      varchar2(100 byte),
    row_key           varchar2(255 byte),
    repeat_status     varchar2(1 byte),
    margin            number
);


